// Requirement: reset other than 0 or 1, or NULL telemetry/bad config -> ADCS_E_NULL
// "without touching history or rejects"
if (reset != 0 || command == NULL || torque == NULL || field == NULL) {
    return ADCS_E_NULL;
}

adcs_vec3_t field_rate = {0, 0, 0};
int is_range = 0;

// Step 3: Check Finite Values for Time, Gain, Limit
// Requirement: Nonfinite time, gain or limit nonfinite or negative -> ADCS_E_RANGE
if (!isfinite(time_s) || !isfinite(gain) || gain < 0.0 || !isfinite(limit) || limit < 0.0) {
    is_range = 1;
}

// Step 4: Check Field Finite
// Requirement: Nonfinite field -> ADCS_E_RANGE
if (!adcs_is_finite_vec3(field)) {
    is_range = 1;
}

// Step 5: Check Time Monotonicity if Initialized
// Requirement: time not strictly newer than stored time -> ADCS_E_RANGE
if (!is_range && sm_state.initialized) {
    if (time_s <= sm_state.previous_time_s) {
        is_range = 1;
    }
}

