// Requirement: field norm <= 1e-12 -> ADCS_E_RANGE
if (!is_range && !sm_state.initialized) {
    double norm = adcs_vec3_norm(field);
    if (norm <= ADCS_EPS_NORM) {
        is_range = 1;
    }
}

