// Requirement: Preserve history, increment rejects, error with zero command/torque
if (is_range) {
    sm_state.rejects++;
    command->command->x = 0.0;
    command->command->y = 0.0;
    command->command->z = 0.0;
    command->saturated_axes = 0U;
    torque->x = 0.0;
    torque->y = 0.0;
    torque->z = 0.0;
    return ADCS_E_RANGE;
}

// Step 8: Process Valid Sample
if (!sm_state.initialized) {
    // Valid first sample: store field/time, set initialized, emit zero
    sm_state.previous_field_t = *field;
    sm_state.previous_time_s = time_s;
    sm_state.initialized = 1;
    sm_state.rejects = 0;

    command->command->x = 0.0;
    command->command->y = 0.0;
    command->command->z = 0.0;
    command->saturated_axes = 0U;
    torque->x = 0.0;
    torque->y = 0.0;
    torque->z = 0.0;

    return ADCS_OK;
} else {
    // Valid later sample: compute rate, dipole, torque
    // bdot_update with alpha 1
    adcs_status_t st_update = adcs_bdot_update(&sm_state, field, time_s, 1.0, &field_rate);

