        sm_state.rejects++;
        command->command->x = 0.0;
        command->command->y = 0.0;
        command->command->z = 0.0;
        command->saturated_axes = 0U;
        torque->x = 0.0;
        torque->y = 0.0;
        torque->z = 0.0;
        return ADCS_E_RANGE;
    }

    // bdot_dipole
    adcs_status_t st_dipole = adcs_bdot_dipole(field, &field_rate, gain, limit, command);

    // Store field/time, clear rejects
    sm_state.previous_field_t = *field;
    sm_state.previous_time_s = time_s;
    sm_state.rejects = 0;

    // Report realized torque: T = m x B
    *torque = adcs_vec3_cross(&command->command, field);

